CREATE OR REPLACE FUNCTION public.fn_b2b_order_billing_eligibility(p_partner_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_order record; v_terms record; v_quote int; v_noprice int; v_ap text; v_fin text;
BEGIN
  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_partner_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('eligible',false,'reason_code','ORDER_NOT_FOUND'); END IF;

  IF v_order.status IN ('cancelado','reprovado','reprovado_sem_itens') THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','ORDER_CANCELED_OR_REJECTED','status',v_order.status);
  END IF;
  IF v_order.status IN ('rascunho','pendente','solicitado','em_analise_comercial',
                        'aguardando_aprovacao_credito','aguardando_ajuste_comercial',
                        'aguardando_itens','aguardando_cotacao') THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','ORDER_NOT_APPROVED','status',v_order.status);
  END IF;

  v_fin := COALESCE(v_order.financial_approval_status,'not_required');
  IF v_fin = 'pending' THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','FINANCIAL_APPROVAL_PENDING');
  END IF;
  IF v_fin = 'rejected' THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','FINANCIAL_APPROVAL_REJECTED');
  END IF;

  SELECT count(*) FILTER (WHERE COALESCE(pricing_mode_snapshot,'') = 'quote_only'),
         count(*) FILTER (WHERE COALESCE(preco_unitario_final_snapshot, preco_unitario, 0) <= 0)
    INTO v_quote, v_noprice
    FROM public.partner_order_items WHERE order_id = p_partner_order_id;
  IF COALESCE(v_quote,0) > 0 THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','QUOTE_ONLY_ITEMS','count',v_quote);
  END IF;
  IF COALESCE(v_noprice,0) > 0 THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','ITEM_WITHOUT_FINAL_PRICE','count',v_noprice);
  END IF;

  -- H6C-001: condição canônica é a vinculada ao pedido; nunca "a mais recente".
  IF v_order.payment_terms_id IS NULL THEN
    IF EXISTS (SELECT 1 FROM public.partner_order_payment_terms t
                WHERE t.partner_order_id = p_partner_order_id) THEN
      RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_NOT_LINKED');
    END IF;
    RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_NOT_DEFINED');
  END IF;

  SELECT * INTO v_terms FROM public.partner_order_payment_terms
   WHERE id = v_order.payment_terms_id AND partner_order_id = p_partner_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_INVALID',
                              'payment_terms_id', v_order.payment_terms_id);
  END IF;

  v_ap := COALESCE(v_terms.approval_status,'pending');
  IF NOT (v_ap = 'approved'
          OR (v_ap = 'not_required' AND v_fin = 'not_required'
              AND COALESCE(v_order.requires_financial_approval,false) = false)) THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','PAYMENT_TERMS_NOT_APPROVED',
                              'approval_status', v_ap, 'payment_terms_id', v_terms.id);
  END IF;

  IF COALESCE(v_terms.final_amount,0) <= 0 THEN
    RETURN jsonb_build_object('eligible',false,'reason_code','NO_FINAL_AMOUNT');
  END IF;

  RETURN jsonb_build_object('eligible',true,'reason_code','OK',
    'final_amount',v_terms.final_amount,'payment_terms_id',v_terms.id,
    'approval_status', v_ap, 'financial_approval_status', v_fin);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_entrega_valor_faturavel_v1(p_entrega_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_e public.entregas%ROWTYPE;
  v_po public.partner_orders%ROWTYPE;
  v_t public.partner_order_payment_terms%ROWTYPE;
  v_fin text;
  v_ap text;
  v_total_snapshot numeric;
  v_origem text;
  v_base numeric;
  v_aceito numeric;
  v_valor numeric;
  v_conf int;
  v_itens jsonb;
  v_ident jsonb;
BEGIN
  SELECT * INTO v_e FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('origem','indisponivel','motivo','entrega_nao_encontrada');
  END IF;

  SELECT count(*)::int INTO v_conf
    FROM public.entrega_conferencia_itens WHERE entrega_id = p_entrega_id;

  -- ------------------- caminho B2B (snapshot canônico) -------------------
  IF v_e.partner_order_id IS NOT NULL THEN
    SELECT * INTO v_po FROM public.partner_orders WHERE id = v_e.partner_order_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('origem','indisponivel','motivo','pedido_b2b_nao_encontrado');
    END IF;

    v_fin := COALESCE(v_po.financial_approval_status, 'not_required');
    v_ident := jsonb_build_object(
      'partner_order_id', v_po.id,
      'payment_terms_id', v_po.payment_terms_id,
      'financial_approval_status', v_fin,
      'order_status', v_po.status);

    IF v_po.payment_terms_id IS NOT NULL THEN
      -- identidade imutável da condição econômica
      SELECT * INTO v_t FROM public.partner_order_payment_terms
       WHERE id = v_po.payment_terms_id;
      IF NOT FOUND OR v_t.partner_order_id IS DISTINCT FROM v_po.id THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','termo_canonico_invalido')
               || v_ident;
      END IF;

      v_ap := COALESCE(v_t.approval_status, 'pending');
      v_ident := v_ident || jsonb_build_object('approval_status', v_ap);

      IF v_ap = 'approved' THEN
        NULL; -- liberado
      ELSIF v_ap = 'not_required'
            AND v_fin = 'not_required'
            AND COALESCE(v_po.requires_financial_approval, false) = false THEN
        NULL; -- liberado: nenhuma aprovação exigida em nenhum nível
      ELSE
        -- pending / rejected / adjustment_requested / incoerência => fail-closed.
        -- Proibido fallback silencioso para outro termo ou para o pedido.
        RETURN jsonb_build_object('origem','bloqueado','motivo','condicao_b2b_nao_liberada')
               || v_ident;
      END IF;

      v_total_snapshot := v_t.final_amount;
      v_origem := 'B2B_PAYMENT_TERMS_SNAPSHOT';
    ELSE
      -- legado: sem condição vinculada ao pedido.
      IF EXISTS (SELECT 1 FROM public.partner_order_payment_terms t
                  WHERE t.partner_order_id = v_po.id) THEN
        -- existe termo, mas não é o canônico do pedido => nunca usar "o mais novo"
        RETURN jsonb_build_object('origem','bloqueado','motivo','termo_nao_vinculado_ao_pedido')
               || v_ident;
      END IF;
      IF v_fin IN ('pending','rejected') THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','aprovacao_financeira_'||v_fin)
               || v_ident;
      END IF;
      IF COALESCE(v_po.status,'') IN ('cancelado','reprovado','reprovado_sem_itens',
                                      'rascunho','pendente','solicitado','em_analise_comercial',
                                      'aguardando_aprovacao_credito','aguardando_ajuste_comercial',
                                      'aguardando_itens','aguardando_cotacao') THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','pedido_nao_faturavel')
               || v_ident;
      END IF;
      v_total_snapshot := COALESCE(v_po.final_amount_with_interest, v_po.total);
      v_origem := 'B2B_ORDER_SNAPSHOT_LEGACY';
    END IF;

    IF v_total_snapshot IS NULL OR v_total_snapshot <= 0 THEN
      RETURN jsonb_build_object('origem','indisponivel','motivo','snapshot_b2b_ausente')
             || v_ident;
    END IF;

    -- base econômica do pedido = soma dos subtotais snapshot dos itens
    SELECT COALESCE(sum(COALESCE(i.subtotal,
             COALESCE(i.preco_unitario_final_snapshot, i.preco_unitario, 0) * COALESCE(i.quantidade,0))), 0)
      INTO v_base
      FROM public.partner_order_items i WHERE i.order_id = v_po.id;

    IF v_conf = 0 OR v_base <= 0 THEN
      RETURN jsonb_build_object('origem', v_origem, 'valor', round(v_total_snapshot,2),
        'metodo', jsonb_build_object('tipo','integral','total_snapshot', round(v_total_snapshot,2),
                                     'base_itens', round(COALESCE(v_base,0),2)))
             || v_ident;
    END IF;

    -- participação econômica aceita POR PRODUTO (volume conferido aceito / volume conferido)
    WITH conf AS (
      SELECT ee.produto_id AS produto_id, ci.status AS status,
             COALESCE(ee.volume,0) * COALESCE(ci.quantidade,1) AS vol
        FROM public.entrega_conferencia_itens ci
        JOIN public.estoque_embalagens ee ON ee.id = ci.embalagem_id
       WHERE ci.entrega_id = p_entrega_id
    ), ratio AS (
      SELECT produto_id,
             CASE WHEN SUM(vol) > 0
                  THEN LEAST(1, round(COALESCE(SUM(vol) FILTER (WHERE status='aceito'), 0) / SUM(vol), 6))
                  ELSE 0 END AS r
        FROM conf GROUP BY produto_id
    ), itens AS (
      SELECT i.product_id AS product_id,
             COALESCE(i.subtotal,
               COALESCE(i.preco_unitario_final_snapshot, i.preco_unitario, 0) * COALESCE(i.quantidade,0)) AS sub,
             COALESCE(r.r, 0) AS r
        FROM public.partner_order_items i
        LEFT JOIN ratio r ON r.produto_id = i.product_id
       WHERE i.order_id = v_po.id
    )
    SELECT COALESCE(sum(sub * r),0),
           COALESCE(jsonb_agg(jsonb_build_object('produto_id', product_id,
                     'subtotal_snapshot', round(sub,2), 'ratio_aceito', r,
                     'base_aceita_item', round(sub * r, 2))
                    ORDER BY product_id), '[]'::jsonb)
      INTO v_aceito, v_itens
      FROM itens;

    IF abs(v_aceito - v_base) <= 0.01 THEN
      v_valor := round(v_total_snapshot, 2);
    ELSE
      -- alocação do ajuste histórico do pedido (juros/desconto de nível pedido)
      -- proporcional à participação econômica aceita dos itens.
      v_valor := round(v_total_snapshot * (v_aceito / v_base), 2);
    END IF;

    RETURN jsonb_build_object('origem', v_origem, 'valor', v_valor,
      'metodo', jsonb_build_object('tipo','participacao_economica_aceita_x_snapshot',
        'total_snapshot', round(v_total_snapshot,2),
        'base_itens', round(v_base,2), 'base_aceita', round(v_aceito,2),
        'fator', round(v_aceito / NULLIF(v_base,0), 6), 'itens', v_itens))
           || v_ident;
  END IF;

  -- ---------------- caminho OS / base de faturamento histórica -------------
  IF v_e.os_faturamento_base_id IS NOT NULL THEN
    SELECT b.valor_total_faturavel INTO v_total_snapshot
      FROM public.os_faturamento_base b WHERE b.id = v_e.os_faturamento_base_id;
    IF v_total_snapshot IS NOT NULL AND v_total_snapshot > 0 THEN
      RETURN jsonb_build_object('origem','OS_FATURAMENTO_BASE_SNAPSHOT',
        'valor', round(v_total_snapshot,2),
        'metodo', jsonb_build_object('tipo','os_base','os_faturamento_base_id', v_e.os_faturamento_base_id));
    END IF;
  END IF;

  RETURN jsonb_build_object('origem','indisponivel','motivo','sem_fonte_historica_confiavel');
END
$function$

CREATE OR REPLACE FUNCTION public.get_report_accountability(_scope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r jsonb;
        _customer uuid := NULLIF(_scope->>'customer_id','')::uuid;
        _from date := (_scope->>'from')::date;
        _to date := (_scope->>'to')::date;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  SELECT jsonb_build_object(
    'scope', _scope,
    'summary', public.get_report_customer_statement(_customer, _from, _to)
  ) INTO r;
  RETURN r;
END;$function$

CREATE OR REPLACE FUNCTION platform_private.c2_owner_order_guard(_uid uuid, _partner uuid, _plan uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  -- Internos e superadmin seguem as regras existentes da função chamadora.
  IF public.is_platform_superadmin(_uid)
     OR public.has_role(_uid,'administrador'::public.app_role) OR public.has_role(_uid,'financeiro'::public.app_role)
     OR public.has_role(_uid,'gestor_comercial'::public.app_role) THEN
    RETURN;
  END IF;
  -- Parceiro com organização própria (fornecedor legado): comportamento inalterado.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN; END IF;
  IF NOT platform_private.c2_owner_order_create_allowed(_uid,_partner) THEN
    RAISE EXCEPTION 'C2_OWNER_ORDER_CLOSED' USING ERRCODE='42501';
  END IF;
  IF _plan IS NULL OR NOT platform_private.c2_owner_plan_assigned(_partner,_plan) THEN
    RAISE EXCEPTION 'plan_not_assigned' USING ERRCODE='42501';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.h15_active_company()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r uuid; n integer;
BEGIN
 PERFORM public.h15_require_staff();
 SELECT count(*),min(id::text)::uuid INTO n,r FROM public.company_fiscal_settings WHERE organization_id=public.h15_actor_organization() AND is_active;
 IF n<>1 THEN RAISE EXCEPTION 'H15_ACTIVE_COMPANY_AMBIGUOUS' USING ERRCODE='42501'; END IF;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_order_actor_scope(_uid uuid, _partner uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s record; r text;
BEGIN
  -- C2_INTERNAL_ORDER_ENTRY_V1: exclusive internal commercial actor (admin/gestor_comercial,
  -- no external B2B role) may target only its own organization's portfolio.
  IF platform_private.b2b_internal_commercial_actor() AND auth.uid() IS NOT DISTINCT FROM _uid THEN
    r := platform_private.c2_internal_order_target_reason(_uid,_partner);
    IF r IS NOT NULL OR _partner IS NULL THEN
      RAISE EXCEPTION 'C2_INTERNAL_TARGET_DENIED:%', COALESCE(r,'target_required') USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  IF public.has_role(_uid,'parceiro_b2b_tecnico'::public.app_role) AND public.has_role(_uid,'parceiro_b2b'::public.app_role)
     AND NOT public.is_platform_superadmin(_uid) THEN
    IF _uid IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
    IF NOT platform_private.c2_owner_order_create_allowed(_uid,_partner) THEN
      RAISE EXCEPTION 'forbidden_financial_terms' USING ERRCODE='42501';
    END IF;
    SELECT * INTO s FROM platform_private.b2b_actor_scope(_uid);
    IF NOT s.profile_ok THEN RAISE EXCEPTION 'inactive_scope' USING ERRCODE='42501'; END IF;
    IF s.org_partner IS DISTINCT FROM _partner OR NOT s.partner_valid
       OR s.user_partner_count <> 1 OR s.user_partner IS DISTINCT FROM _partner THEN
      RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  PERFORM platform_private.assert_b2b_partner_scope(_uid,_partner);
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_external_origin_assert(s jsonb, partner uuid, client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid:=auth.uid(); org uuid; p public.partner_accounts;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.partner_accounts WHERE id=partner FOR SHARE;
 org:=p.commercial_owner_organization_id;
 IF NOT FOUND OR p.ativo IS NOT TRUE OR p.deleted_at IS NOT NULL OR org IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=org AND o.ativo AND o.status='ativa')
 OR EXISTS(SELECT 1 FROM public.organizations o WHERE o.partner_account_id=partner)
 OR NOT platform_private.c2_external_origin_contract_valid(s)
 OR s->>'organization_id' IS DISTINCT FROM org::text OR s->>'partner_id' IS DISTINCT FROM partner::text
 THEN RAISE EXCEPTION 'C2_EXTERNAL_ORIGIN_DENIED' USING ERRCODE='42501'; END IF;
 IF client IS DISTINCT FROM p.client_id OR (client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=client AND c.organization_id=org))
 THEN RAISE EXCEPTION 'C2_EXTERNAL_CLIENT_DENIED' USING ERRCODE='42501'; END IF;
 -- Initial writes are authorized only inside the existing canonical create transaction.
 -- Subsequent administration uses P1's active internal owner authority, never buyer roles.
 IF platform_private.has_ticket('c2_external_order_create',partner) THEN
  IF s->>'actor_user_id' IS DISTINCT FROM uid::text OR NOT platform_private.c2_owner_order_create_allowed(uid,partner)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_CREATE_DENIED' USING ERRCODE='42501'; END IF;
  ELSE
  IF public.h15_actor_organization() IS DISTINCT FROM org OR NOT platform_private.c2p1_settings_allowed(partner,true)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_OWNER_DENIED' USING ERRCODE='42501'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_owner_order_create_allowed(_uid uuid, _partner uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c jsonb;
BEGIN
  -- c2_ord_writer_v1: nunca confia em parâmetro de uid que não seja o JWT atual.
  IF _uid IS NULL OR _partner IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RETURN false; END IF;
  -- Gestor B2B vigente (user_roles canônico; revogação remove a linha). Técnico isolado nunca compra.
  IF NOT public.has_role(_uid,'parceiro_b2b'::public.app_role) THEN RETURN false; END IF;
  c := platform_private.b2b_commercial_context();
  IF c IS NULL OR c->>'contract' <> 'C2_MULTIPROFILE_V1' OR c->>'mode' <> 'commercial_owner'
     OR (c->>'partner_id')::uuid IS DISTINCT FROM _partner OR COALESCE((c->>'manager')::boolean,false) IS NOT TRUE THEN
    RETURN false;
  END IF;
  -- Cliente comercial = sem organização própria; tenant dono ativo e coerente com perfil/vínculo.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN false; END IF;
  IF NOT COALESCE(platform_private.b2b_phase1_partner_visible(_partner,true),false) THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_users pu
      JOIN public.partner_accounts pa ON pa.id = pu.partner_id
      JOIN public.profiles p ON p.user_id = pu.user_id
      JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pu.user_id = _uid AND pu.partner_id = _partner
       AND pu.revoked_at IS NULL AND (pu.valid_from IS NULL OR pu.valid_from <= now())
       AND pa.ativo AND pa.deleted_at IS NULL AND o.ativo AND o.status = 'ativa'
       AND (o.partner_account_id IS NULL OR o.partner_account_id = _partner)
       AND p.ativo AND p.organization_id = pu.tenant_id AND pu.tenant_id = o.id
       AND (c->>'tenant_id')::uuid = o.id
       AND public.is_valid_b2b_partner_user(_uid, pa.id)) THEN
    RETURN false;
  END IF;
  RETURN EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'pedidos_b2b')
     AND EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'catalogo_precos');
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_partner_order_attempt_authz(p_uid uuid, p_partner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_is_internal boolean; v_is_partner boolean; v_is_partner_tech boolean; v_user_partner uuid;
BEGIN
  -- Espelha a autorização do create canônico (mesma ordem/mensagens). Chamado antes E
  -- depois do lock b2b_idem; cada chamada lê um snapshot novo (READ COMMITTED).
  IF p_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  PERFORM platform_private.c2_order_actor_scope(p_uid, p_partner_id);
  v_is_internal := public.has_role(p_uid,'administrador'::public.app_role)
                OR public.has_role(p_uid,'financeiro'::public.app_role)
                OR public.has_role(p_uid,'gestor_comercial'::public.app_role);
  v_is_partner      := public.has_role(p_uid,'parceiro_b2b'::public.app_role);
  v_is_partner_tech := public.has_role(p_uid,'parceiro_b2b_tecnico'::public.app_role);
  v_user_partner    := public.get_user_partner_id();
  IF public.has_role(p_uid,'cliente_produtor'::public.app_role) AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED';
  END IF;
  IF v_is_partner_tech AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'partner_tech_cannot_create_order';
  END IF;
  IF NOT v_is_internal THEN
    IF NOT v_is_partner OR v_user_partner IS NULL OR v_user_partner <> p_partner_id THEN
      RAISE EXCEPTION 'forbidden_partner';
    END IF;
  END IF;
  PERFORM 1 FROM public.partner_accounts WHERE id = p_partner_id AND ativo = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'partner_not_found'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_calc_next_generation_date(_freq text, _from_date date, _due_day integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_next DATE;
BEGIN
  CASE _freq
    WHEN 'MONTHLY' THEN v_next := (_from_date + INTERVAL '1 month')::DATE;
    WHEN 'WEEKLY' THEN v_next := (_from_date + INTERVAL '1 week')::DATE;
    WHEN 'BIWEEKLY' THEN v_next := (_from_date + INTERVAL '2 weeks')::DATE;
    WHEN 'QUARTERLY' THEN v_next := (_from_date + INTERVAL '3 months')::DATE;
    WHEN 'YEARLY' THEN v_next := (_from_date + INTERVAL '1 year')::DATE;
    ELSE v_next := (_from_date + INTERVAL '1 month')::DATE;
  END CASE;
  IF _due_day IS NOT NULL AND _freq IN ('MONTHLY','QUARTERLY','YEARLY') THEN
    BEGIN
      v_next := make_date(EXTRACT(YEAR FROM v_next)::INT, EXTRACT(MONTH FROM v_next)::INT,
        LEAST(_due_day, EXTRACT(DAY FROM (date_trunc('month', v_next) + INTERVAL '1 month - 1 day'))::INT));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  RETURN v_next;
END $function$

CREATE OR REPLACE FUNCTION public.fn_entrega_guard_faturamento_v1(p_entrega_id uuid, p_total numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_r public.entrega_reconciliacoes%ROWTYPE;
  v_conf int;
  v_canon jsonb;
  v_max numeric;
  v_canon_valor numeric;
BEGIN
  SELECT count(*)::int INTO v_conf
    FROM public.entrega_conferencia_itens WHERE entrega_id = p_entrega_id;

  v_canon := public.fn_entrega_valor_faturavel_v1(p_entrega_id);

  -- H6C-001: condição comercial pendente/rejeitada/não vinculada bloqueia o
  -- faturamento em qualquer modo, inclusive o manual.
  IF (v_canon->>'origem') = 'bloqueado' THEN
    RAISE EXCEPTION 'condicao_b2b_bloqueada: %', COALESCE(v_canon->>'motivo','indefinido')
      USING ERRCODE='check_violation';
  END IF;

  v_canon_valor := NULLIF(v_canon->>'valor','')::numeric;

  IF v_conf = 0 THEN
    -- H6c-003: entrega integral também é comparada ao canônico, quando existir.
    IF v_canon_valor IS NOT NULL AND p_total IS NOT NULL
       AND abs(p_total - v_canon_valor) > 0.01 THEN
      RAISE EXCEPTION 'valor_divergente_do_canonico: informado=%, canonico=%',
        round(p_total,2), round(v_canon_valor,2) USING ERRCODE='check_violation';
    END IF;
    IF v_canon_valor IS NULL THEN
      -- sem fonte histórica confiável: fluxo legado/manual, o guard não arbitra preço.
      RETURN jsonb_build_object('modo','legado','ratio_aceito',1,'canonico',v_canon);
    END IF;
    RETURN jsonb_build_object('modo','integral_canonico','ratio_aceito',1,
                              'valor_faturavel_max', round(v_canon_valor,2),
                              'canonico', v_canon);
  END IF;

  SELECT * INTO v_r FROM public.entrega_reconciliacoes
   WHERE entrega_id = p_entrega_id AND status = 'reconciliada';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'entrega_nao_reconciliada: conclua a conferencia e a reconciliacao antes de faturar'
      USING ERRCODE='check_violation';
  END IF;
  IF NOT v_r.faturavel THEN
    RAISE EXCEPTION 'entrega_nao_faturavel: todos os itens foram recusados'
      USING ERRCODE='check_violation';
  END IF;

  v_max := COALESCE(v_r.valor_faturavel_max, v_canon_valor);
  IF v_max IS NOT NULL AND p_total > v_max + 0.01 THEN
    RAISE EXCEPTION 'valor_acima_do_aceito' USING ERRCODE='check_violation';
  END IF;

  RETURN jsonb_build_object('modo', 'reconciliado', 'reconciliacao_id', v_r.id,
                            'ratio_aceito', v_r.ratio_aceito,
                            'valor_faturavel_max', v_max, 'canonico', v_canon);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_resolve_b2b_cart(p_partner_id uuid, p_plan_id uuid, p_items jsonb, p_ref_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item jsonb; v_iid uuid; v_itipo text; v_qty numeric(12,2);
  v_unidade text; v_volume_ml numeric(12,2);
  v_nome text; v_codigo text; v_res jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_table numeric(14,2) := 0; v_net numeric(14,2) := 0;
  v_quote boolean := false;
  v_line_table numeric(14,2); v_line_final numeric(14,2);
  v_ok boolean; v_active boolean; v_b2b boolean;
BEGIN
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'empty_cart' USING ERRCODE='P0001';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_iid     := COALESCE(NULLIF(v_item->>'item_id','')::uuid, NULLIF(v_item->>'product_id','')::uuid);
    v_itipo   := COALESCE(NULLIF(v_item->>'item_tipo',''), 'produto');
    v_qty     := COALESCE((v_item->>'quantidade')::numeric, 0);
    v_unidade := COALESCE(NULLIF(v_item->>'unidade_medida',''), 'hectare');
    v_volume_ml := NULLIF((v_item->>'volume_ml')::numeric, 0);

    IF v_iid IS NULL THEN RAISE EXCEPTION 'invalid_item' USING ERRCODE='P0001'; END IF;
    IF v_qty <= 0 THEN RAISE EXCEPTION 'invalid_qty' USING ERRCODE='P0001'; END IF;
    IF v_unidade NOT IN ('hectare','litro','dose','unidade') THEN
      RAISE EXCEPTION 'invalid_unidade_medida' USING ERRCODE='P0001'; END IF;
    IF v_unidade = 'unidade' AND COALESCE(v_volume_ml,0) <= 0 THEN
      RAISE EXCEPTION 'invalid_volume_ml' USING ERRCODE='P0001'; END IF;

    IF v_itipo = 'produto' THEN
      SELECT nome, codigo, ativo, COALESCE(b2b_enabled,true) INTO v_nome, v_codigo, v_active, v_b2b
        FROM public.produtos WHERE id = v_iid;
    ELSIF v_itipo = 'microrganismo' THEN
      SELECT nome, codigo, ativo, COALESCE(b2b_enabled,false) INTO v_nome, v_codigo, v_active, v_b2b
        FROM public.microrganismos WHERE id = v_iid;
    ELSE
      RAISE EXCEPTION 'invalid_item_tipo' USING ERRCODE='P0001';
    END IF;
    IF v_nome IS NULL OR v_active IS NOT TRUE OR v_b2b IS NOT TRUE THEN
      RAISE EXCEPTION 'product_unavailable' USING ERRCODE='P0001';
    END IF;

    v_res := public.fn_resolve_commercial_price(
      'partner', p_partner_id, NULL, p_plan_id,
      CASE WHEN v_itipo='produto' THEN v_iid END,
      CASE WHEN v_itipo='microrganismo' THEN v_iid END,
      v_unidade, v_volume_ml, COALESCE(p_ref_date, current_date), v_qty);

    v_ok := COALESCE((v_res->>'ok')::boolean,false);

    IF COALESCE((v_res->>'quote_required')::boolean,false) THEN
      v_quote := true;
      v_line_table := 0; v_line_final := 0;
    ELSIF NOT v_ok THEN
      RAISE EXCEPTION '%', v_res->>'reason_code' USING ERRCODE='P0001';
    ELSE
      v_line_table := ROUND((v_res->>'base_price')::numeric * v_qty, 2);
      v_line_final := ROUND((v_res->>'final_unit_price')::numeric * v_qty, 2);
      v_table := v_table + v_line_table;
      v_net   := v_net + v_line_final;
    END IF;

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'item_id', v_iid, 'item_tipo', v_itipo, 'quantidade', v_qty,
      'unidade_medida', v_unidade, 'volume_ml', v_volume_ml,
      'nome', v_nome, 'codigo', v_codigo,
      'pricing_mode', v_res->>'pricing_mode',
      'price_source', v_res->>'price_source',
      'reason_code',  v_res->>'reason_code',
      'quote_required', COALESCE((v_res->>'quote_required')::boolean,false),
      'base_price', (v_res->>'base_price')::numeric,
      'condition_price', (v_res->>'condition_price')::numeric,
      'plan_discount_percent', (v_res->>'plan_discount_percent')::numeric,
      'min_quantity', (v_res->>'min_quantity')::numeric,
      'final_unit_price', (v_res->>'final_unit_price')::numeric,
      'rule_id', v_res->>'rule_id',
      'line_table_amount', v_line_table,
      'line_final_amount', v_line_final
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'quote_required', v_quote,
    'table_amount', CASE WHEN v_quote THEN 0 ELSE v_table END,
    'discount_amount', CASE WHEN v_quote THEN 0 ELSE ROUND(v_table - v_net,2) END,
    'net_amount', CASE WHEN v_quote THEN 0 ELSE v_net END,
    'lines', v_lines);
END $function$

CREATE OR REPLACE FUNCTION platform_private.b2b_internal_assert_origin(s jsonb, partner uuid, client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; uid uuid:=auth.uid();
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL OR NOT public.fn_cc_can_prepare(uid) OR NOT public._saas_user_has_feature(uid,'pedidos_b2b') THEN RAISE EXCEPTION 'B2B_INTERNAL_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT platform_private.b2b_internal_origin_valid(s) OR s->>'organization_id' IS DISTINCT FROM org::text OR s->>'partner_id' IS DISTINCT FROM partner::text THEN RAISE EXCEPTION 'B2B_INTERNAL_ORIGIN_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.partner_accounts p WHERE p.id=partner AND p.commercial_owner_organization_id=org AND p.ativo IS TRUE AND p.deleted_at IS NULL
 AND (p.client_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=p.client_id AND c.organization_id=org))) THEN RAISE EXCEPTION 'B2B_INTERNAL_PARTNER_DENIED' USING ERRCODE='42501'; END IF;
 IF client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=client AND c.organization_id=org) THEN RAISE EXCEPTION 'B2B_INTERNAL_CLIENT_DENIED' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION platform_private.assert_b2b_partner_scope(_uid uuid, _partner uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s record;
BEGIN
  IF _uid IS NULL OR auth.uid() IS NULL OR _uid <> auth.uid() THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE='42501';
  END IF;
  IF _partner IS NULL OR NOT EXISTS (SELECT 1 FROM public.partner_accounts pa
       WHERE pa.id = _partner AND pa.ativo = true AND pa.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'partner_not_found' USING ERRCODE='42501';
  END IF;
  IF public.is_platform_superadmin(_uid) THEN RETURN; END IF;
  IF public.has_role(_uid,'parceiro_b2b_tecnico'::app_role) THEN
    RAISE EXCEPTION 'forbidden_financial_terms' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM platform_private.b2b_actor_scope(_uid);
  IF NOT s.profile_ok THEN RAISE EXCEPTION 'inactive_scope' USING ERRCODE='42501'; END IF;
  IF s.org_partner IS DISTINCT FROM _partner OR NOT s.partner_valid THEN
    RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
  END IF;
  IF public.has_role(_uid,'parceiro_b2b'::app_role) THEN
    IF s.user_partner_count <> 1 OR s.user_partner IS DISTINCT FROM _partner THEN
      RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  IF NOT (public.has_role(_uid,'administrador'::app_role) OR public.has_role(_uid,'financeiro'::app_role)
          OR public.has_role(_uid,'gestor_comercial'::app_role)) THEN
    RAISE EXCEPTION 'forbidden_role' USING ERRCODE='42501';
  END IF;
END $function$

